#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

class Solution {
public:
    std::string arrangeWords(std::string text) {
        std::stringstream ss(text);
        std::string word;
        std::vector<std::string> words;
        while (ss >> word) words.push_back(word);
        words[0][0] = std::tolower(words[0][0]);
        std::stable_sort(words.begin(), words.end(), [](const std::string& a, const std::string& b) {
            return a.size() < b.size();
        });
        words[0][0] = std::toupper(words[0][0]);
        std::string res = words[0];
        for (int i = 1; i < (int)words.size(); ++i) {
            res += " " + words[i];
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String arrangeWords(String text) {
        String[] words = text.split(" ");
        words[0] = words[0].toLowerCase();
        Arrays.sort(words, (a, b) -> Integer.compare(a.length(), b.length()));
        words[0] = Character.toUpperCase(words[0].charAt(0)) + words[0].substring(1);
        return String.join(" ", words);
    }
}

var arrangeWords = function(text) {
    const words = text.split(" ");
    words[0] = words[0].toLowerCase();
    words.sort((a, b) => a.length - b.length);
    words[0] = words[0].charAt(0).toUpperCase() + words[0].slice(1);
    return words.join(" ");
};
